-- Sprint 4: typed feed inventory, perpetual weighted-average costing, purchases and forecasting.
create table public.feed_types(id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id)on delete cascade,name text not null,default_bag_size_kg numeric(14,3)not null check(default_bag_size_kg>0),description text,active boolean not null default true,created_at timestamptz not null default now(),created_by uuid not null references public.profiles(id),updated_at timestamptz not null default now(),updated_by uuid references public.profiles(id));
create unique index feed_types_farm_name_uidx on public.feed_types(farm_id,lower(name));create index feed_types_farm_active_idx on public.feed_types(farm_id,active);
create table public.suppliers(id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id)on delete cascade,name text not null check(char_length(trim(name))between 2 and 160),phone text,email text,location text,notes text,active boolean not null default true,created_at timestamptz not null default now(),created_by uuid not null references public.profiles(id),updated_at timestamptz not null default now(),updated_by uuid references public.profiles(id));
create unique index suppliers_farm_name_uidx on public.suppliers(farm_id,lower(name));create index suppliers_farm_active_idx on public.suppliers(farm_id,active);
alter table public.daily_production_records add column feed_type_id uuid references public.feed_types(id)on delete restrict;
alter table public.daily_production_records add constraint production_feed_type_required check(feed_consumed_kg=0 or feed_type_id is not null)not valid;
alter table public.feed_inventory_movements drop constraint feed_inventory_movements_movement_type_check,drop constraint feed_inventory_movements_direction_check;
alter table public.feed_inventory_movements add column feed_type_id uuid references public.feed_types(id)on delete restrict;
alter table public.feed_inventory_movements add constraint feed_movement_type_check check(movement_type in('opening_stock','purchase','consumption','wastage','adjustment','purchase_reversal'));
alter table public.feed_inventory_movements add constraint feed_movement_direction_check check((movement_type in('opening_stock','purchase')and direction='IN')or(movement_type in('consumption','wastage','purchase_reversal')and direction='OUT')or movement_type='adjustment');
alter table public.feed_inventory_movements add constraint new_feed_movement_type_required check(feed_type_id is not null or source_type='legacy_sprint_2')not valid;
create index feed_movements_farm_type_date_idx on public.feed_inventory_movements(farm_id,feed_type_id,movement_date,created_at,id);
create table public.feed_purchases(id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id)on delete cascade,supplier_id uuid references public.suppliers(id)on delete restrict,feed_type_id uuid not null references public.feed_types(id)on delete restrict,purchase_number text not null,purchase_date date not null,bags numeric(14,3)not null check(bags>0),bag_size_kg numeric(14,3)not null check(bag_size_kg>0),total_kg numeric(14,3)not null check(total_kg>0),cost_per_bag numeric(14,2)not null check(cost_per_bag>=0),cost_per_kg numeric(14,4)not null check(cost_per_kg>=0),total_cost numeric(14,2)not null check(total_cost>=0),notes text,status text not null default'completed'check(status in('completed','voided')),voided_at timestamptz,voided_by uuid references public.profiles(id),void_reason text,created_at timestamptz not null default now(),created_by uuid not null references public.profiles(id),updated_at timestamptz not null default now(),updated_by uuid references public.profiles(id),unique(farm_id,purchase_number));
create index feed_purchases_farm_date_idx on public.feed_purchases(farm_id,purchase_date desc);create index feed_purchases_type_date_idx on public.feed_purchases(feed_type_id,purchase_date desc);create index feed_purchases_supplier_date_idx on public.feed_purchases(supplier_id,purchase_date desc);
create table public.feed_purchase_payments(id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id)on delete cascade,feed_purchase_id uuid not null references public.feed_purchases(id)on delete restrict,payment_date date not null,amount numeric(14,2)not null check(amount>0),payment_method text not null check(payment_method in('cash','momo','bank_transfer','other')),reference text,notes text,voided_at timestamptz,voided_by uuid references public.profiles(id),void_reason text,created_at timestamptz not null default now(),created_by uuid not null references public.profiles(id));create index feed_purchase_payments_purchase_idx on public.feed_purchase_payments(feed_purchase_id);
create table public.feed_inventory_balances(farm_id uuid not null references public.farms(id)on delete cascade,feed_type_id uuid not null references public.feed_types(id)on delete cascade,quantity_kg numeric(14,3)not null default 0,inventory_value numeric(14,2)not null default 0,weighted_average_cost numeric(14,4)not null default 0,updated_at timestamptz not null default now(),primary key(farm_id,feed_type_id));
create trigger feed_types_updated_at before update on public.feed_types for each row execute function public.set_updated_at();create trigger suppliers_updated_at before update on public.suppliers for each row execute function public.set_updated_at();create trigger feed_purchases_updated_at before update on public.feed_purchases for each row execute function public.set_updated_at();

-- Same-date order: opening, purchase, positive adjustment, consumption, wastage, negative adjustment/reversal; then created_at and id.
create function public.recalculate_feed_ledger(target_farm uuid,target_feed_type uuid)returns void language plpgsql security definer set search_path='' as $$declare m record;q numeric:=0;v numeric:=0;w numeric:=0;c numeric;begin
 perform pg_advisory_xact_lock(hashtextextended(target_farm::text||target_feed_type::text,0));
 for m in select*from public.feed_inventory_movements where farm_id=target_farm and feed_type_id=target_feed_type order by movement_date,case when movement_type='opening_stock'then 1 when movement_type='purchase'then 2 when movement_type='adjustment'and direction='IN'then 3 when movement_type='consumption'then 4 when movement_type='wastage'then 5 else 6 end,created_at,id loop
  if m.direction='IN'then c:=coalesce(m.unit_cost_snapshot,0);q:=q+m.quantity_kg;v:=round(v+m.quantity_kg*c,2);w:=case when q=0 then 0 else round(v/q,4)end;update public.feed_inventory_movements set unit_cost_snapshot=c,total_cost_snapshot=round(m.quantity_kg*c,2)where id=m.id;
  else if m.quantity_kg>q then raise exception'Only % kg feed is available on %',q,m.movement_date using errcode='23514';end if;c:=w;q:=q-m.quantity_kg;v:=case when q=0 then 0 else round(v-m.quantity_kg*c,2)end;w:=case when q=0 then 0 else round(v/q,4)end;update public.feed_inventory_movements set unit_cost_snapshot=c,total_cost_snapshot=round(m.quantity_kg*c,2)where id=m.id;end if;
 end loop;
 insert into public.feed_inventory_balances(farm_id,feed_type_id,quantity_kg,inventory_value,weighted_average_cost,updated_at)values(target_farm,target_feed_type,q,v,w,now())on conflict(farm_id,feed_type_id)do update set quantity_kg=excluded.quantity_kg,inventory_value=excluded.inventory_value,weighted_average_cost=excluded.weighted_average_cost,updated_at=now();
end;$$;
create function public.feed_access_farm(required_roles text[])returns uuid language plpgsql security definer set search_path='' as $$declare f uuid;begin select farm_id into f from public.farm_members where user_id=auth.uid()and active and role=any(required_roles)order by created_at limit 1;if f is null then raise exception'Feed access denied'using errcode='42501';end if;return f;end;$$;
create function public.create_feed_type(name text,default_bag_size_kg numeric,description text default null)returns public.feed_types language plpgsql security definer set search_path='' as $$declare f uuid;r public.feed_types;begin f:=public.feed_access_farm(array['admin','manager']);insert into public.feed_types(farm_id,name,default_bag_size_kg,description,created_by)values(f,trim(name),default_bag_size_kg,nullif(trim(description),''),auth.uid())returning*into r;return r;end;$$;
create function public.update_feed_type(target_feed_type uuid,name text,default_bag_size_kg numeric,active boolean,description text default null)returns public.feed_types language plpgsql security definer set search_path='' as $$declare r public.feed_types;begin update public.feed_types set name=trim($2),default_bag_size_kg=$3,active=$4,description=nullif(trim($5),''),updated_by=auth.uid()where id=$1 and public.has_farm_role(farm_id,array['admin','manager'])returning*into r;if r.id is null then raise exception'Feed type access denied'using errcode='42501';end if;return r;end;$$;
create function public.create_supplier(name text,phone text,email text,location text,notes text default null)returns public.suppliers language plpgsql security definer set search_path='' as $$declare f uuid;r public.suppliers;begin f:=public.feed_access_farm(array['admin','manager']);insert into public.suppliers(farm_id,name,phone,email,location,notes,created_by)values(f,trim(name),nullif(trim(phone),''),nullif(trim(email),''),nullif(trim(location),''),nullif(trim(notes),''),auth.uid())returning*into r;return r;end;$$;
create function public.update_supplier(target_supplier uuid,name text,phone text,email text,location text,active boolean,notes text default null)returns public.suppliers language plpgsql security definer set search_path='' as $$declare r public.suppliers;begin update public.suppliers set name=trim($2),phone=nullif(trim($3),''),email=nullif(trim($4),''),location=nullif(trim($5),''),active=$6,notes=nullif(trim($7),''),updated_by=auth.uid()where id=$1 and public.has_farm_role(farm_id,array['admin','manager'])returning*into r;if r.id is null then raise exception'Supplier access denied'using errcode='42501';end if;return r;end;$$;
create function public.set_opening_feed_stock(feed_type_id uuid,effective_date date,bags numeric,bag_size_kg numeric,cost_per_bag numeric,notes text default null)returns public.feed_inventory_movements language plpgsql security definer set search_path='' as $$declare f uuid;r public.feed_inventory_movements;begin f:=public.feed_access_farm(array['admin']);if not exists(select 1 from public.feed_types ft where ft.id=$1 and ft.farm_id=f)then raise exception'Invalid feed type'using errcode='42501';end if;if exists(select 1 from public.feed_inventory_movements fm where fm.farm_id=f and fm.feed_type_id=$1 and fm.movement_type='opening_stock')then raise exception'Opening stock already exists'using errcode='23505';end if;insert into public.feed_inventory_movements(farm_id,feed_type_id,movement_date,movement_type,direction,quantity_kg,unit_cost_snapshot,total_cost_snapshot,source_type,notes,created_by)values(f,$1,$2,'opening_stock','IN',round($3*$4,3),round($5/$4,4),round($3*$5,2),'opening_feed_stock',nullif(trim($6),''),auth.uid())returning*into r;perform public.recalculate_feed_ledger(f,$1);return r;end;$$;
create function public.post_feed_purchase(supplier_id uuid,feed_type_id uuid,purchase_date date,bags numeric,bag_size_kg numeric,cost_per_bag numeric,amount_paid numeric,payment_method text,reference text default null,notes text default null)returns public.feed_purchases language plpgsql security definer set search_path='' as $$declare f uuid;r public.feed_purchases;kg numeric;total numeric;cpk numeric;sn text;begin f:=public.feed_access_farm(array['admin','manager']);perform pg_advisory_xact_lock(hashtextextended(f::text||$2::text,0));if not exists(select 1 from public.feed_types where id=$2 and farm_id=f and active)or($1 is not null and not exists(select 1 from public.suppliers where id=$1 and farm_id=f and active))then raise exception'Invalid feed type or supplier'using errcode='42501';end if;if $4<=0 or $5<=0 or $6<0 then raise exception'Invalid purchase values'using errcode='22023';end if;kg:=round($4*$5,3);total:=round($4*$6,2);cpk:=case when kg=0 then 0 else round(total/kg,4)end;if $7<0 or $7>total then raise exception'Payment exceeds purchase total'using errcode='23514';end if;sn:='FEED-'||to_char($3,'YYYYMMDD')||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8));insert into public.feed_purchases(farm_id,supplier_id,feed_type_id,purchase_number,purchase_date,bags,bag_size_kg,total_kg,cost_per_bag,cost_per_kg,total_cost,notes,created_by)values(f,$1,$2,sn,$3,$4,$5,kg,$6,cpk,total,nullif(trim($10),''),auth.uid())returning*into r;insert into public.feed_inventory_movements(farm_id,feed_type_id,movement_date,movement_type,direction,quantity_kg,unit_cost_snapshot,total_cost_snapshot,source_type,source_id,created_by)values(f,$2,$3,'purchase','IN',kg,cpk,total,'feed_purchase',r.id,auth.uid());if $7>0 then insert into public.feed_purchase_payments(farm_id,feed_purchase_id,payment_date,amount,payment_method,reference,created_by)values(f,r.id,$3,$7,$8,nullif(trim($9),''),auth.uid());end if;perform public.recalculate_feed_ledger(f,$2);return r;end;$$;
create function public.record_feed_purchase_payment(target_purchase uuid,payment_date date,amount numeric,payment_method text,reference text default null,notes text default null)returns public.feed_purchase_payments language plpgsql security definer set search_path='' as $$declare p public.feed_purchases;paid numeric;r public.feed_purchase_payments;begin select*into p from public.feed_purchases where id=$1 for update;if p.id is null or p.status<>'completed'or not public.has_farm_role(p.farm_id,array['admin','manager'])then raise exception'Payment access denied'using errcode='42501';end if;select coalesce(sum(x.amount),0)into paid from public.feed_purchase_payments x where x.feed_purchase_id=p.id and x.voided_at is null;if $3<=0 or paid+$3>p.total_cost then raise exception'Payment exceeds remaining balance'using errcode='23514';end if;insert into public.feed_purchase_payments(farm_id,feed_purchase_id,payment_date,amount,payment_method,reference,notes,created_by)values(p.farm_id,p.id,$2,$3,$4,nullif(trim($5),''),nullif(trim($6),''),auth.uid())returning*into r;return r;end;$$;
create function public.update_feed_purchase(target_purchase uuid,supplier_id uuid,purchase_date date,bags numeric,bag_size_kg numeric,cost_per_bag numeric,notes text default null)returns public.feed_purchases language plpgsql security definer set search_path='' as $$declare p public.feed_purchases;r public.feed_purchases;paid numeric;kg numeric;total numeric;begin select*into p from public.feed_purchases where id=$1 for update;if p.id is null or p.status<>'completed'or not public.has_farm_role(p.farm_id,array['admin','manager'])then raise exception'Purchase edit denied'using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended(p.farm_id::text||p.feed_type_id::text,0));if $2 is not null and not exists(select 1 from public.suppliers where id=$2 and farm_id=p.farm_id)then raise exception'Invalid supplier'using errcode='42501';end if;kg:=round($4*$5,3);total:=round($4*$6,2);select coalesce(sum(amount),0)into paid from public.feed_purchase_payments where feed_purchase_id=p.id and voided_at is null;if $4<=0 or $5<=0 or $6<0 or total<paid then raise exception'Invalid purchase edit or total below payments'using errcode='23514';end if;update public.feed_purchases set supplier_id=$2,purchase_date=$3,bags=$4,bag_size_kg=$5,total_kg=kg,cost_per_bag=$6,cost_per_kg=round(total/kg,4),total_cost=total,notes=nullif(trim($7),''),updated_by=auth.uid()where id=p.id returning*into r;update public.feed_inventory_movements set movement_date=$3,quantity_kg=kg,unit_cost_snapshot=round(total/kg,4),total_cost_snapshot=total where source_type='feed_purchase'and source_id=p.id and movement_type='purchase';perform public.recalculate_feed_ledger(p.farm_id,p.feed_type_id);return r;end;$$;
create function public.void_feed_purchase_payment(target_payment uuid,reason text)returns void language plpgsql security definer set search_path='' as $$declare f uuid;begin select farm_id into f from public.feed_purchase_payments where id=$1 for update;if f is null or not public.has_farm_role(f,array['admin'])or char_length(trim($2))<3 then raise exception'Payment void denied'using errcode='42501';end if;update public.feed_purchase_payments set voided_at=now(),voided_by=auth.uid(),void_reason=trim($2)where id=$1 and voided_at is null;end;$$;
create function public.void_feed_purchase(target_purchase uuid,reason text)returns void language plpgsql security definer set search_path='' as $$declare p public.feed_purchases;begin select*into p from public.feed_purchases where id=$1 for update;if p.id is null or p.status<>'completed'or not public.has_farm_role(p.farm_id,array['admin'])or char_length(trim($2))<3 then raise exception'Purchase void denied'using errcode='42501';end if;if exists(select 1 from public.feed_purchase_payments where feed_purchase_id=p.id and voided_at is null)then raise exception'Active payments must be voided first'using errcode='23514';end if;insert into public.feed_inventory_movements(farm_id,feed_type_id,movement_date,movement_type,direction,quantity_kg,source_type,source_id,created_by)values(p.farm_id,p.feed_type_id,p.purchase_date,'purchase_reversal','OUT',p.total_kg,'feed_purchase_reversal',p.id,auth.uid());update public.feed_purchases set status='voided',voided_at=now(),voided_by=auth.uid(),void_reason=trim($2),updated_by=auth.uid()where id=p.id;perform public.recalculate_feed_ledger(p.farm_id,p.feed_type_id);end;$$;
create function public.create_feed_adjustment(feed_type_id uuid,movement_date date,movement_type text,direction text,quantity_kg numeric,unit_cost numeric,reason text,notes text default null)returns public.feed_inventory_movements language plpgsql security definer set search_path='' as $$declare f uuid;r public.feed_inventory_movements;w numeric;begin f:=public.feed_access_farm(array['admin']);if $3 not in('adjustment','wastage')or $4 not in('IN','OUT')or($3='wastage'and $4<>'OUT')or $5<=0 or char_length(trim($7))<3 then raise exception'Invalid adjustment'using errcode='22023';end if;if not exists(select 1 from public.feed_types ft where ft.id=$1 and ft.farm_id=f)then raise exception'Invalid feed type'using errcode='42501';end if;select b.weighted_average_cost into w from public.feed_inventory_balances b where b.farm_id=f and b.feed_type_id=$1;if $4='IN'and coalesce($6,-1)<0 then raise exception'Positive adjustment requires cost basis'using errcode='22023';end if;insert into public.feed_inventory_movements(farm_id,feed_type_id,movement_date,movement_type,direction,quantity_kg,unit_cost_snapshot,source_type,notes,created_by)values(f,$1,$2,$3,$4,$5,case when $4='IN'then $6 else w end,'feed_adjustment',trim($7)||case when nullif(trim($8),'')is null then''else': '||trim($8)end,auth.uid())returning*into r;perform public.recalculate_feed_ledger(f,$1);return r;end;$$;

-- Replace Sprint 2 production RPCs with typed-feed variants.
drop function public.create_daily_production(uuid,date,integer,integer,integer,integer,numeric,numeric,numeric,text);drop function public.update_daily_production(uuid,integer,integer,integer,integer,numeric,numeric,numeric,text);
create function public.create_daily_production(target_flock_id uuid,production_date date,eggs_collected integer,cracked_eggs integer,deaths integer,culls integer,feed_consumed_kg numeric,feed_type_id uuid,transport_cost numeric,other_cost numeric,notes text default null)returns public.daily_production_records language plpgsql security definer set search_path='' as $$declare f uuid;st text;role text;tz text;available integer;r public.daily_production_records;begin if auth.uid()is null then raise exception'Authentication required'using errcode='42501';end if;select x.farm_id,x.status,fa.timezone into f,st,tz from public.flocks x join public.farms fa on fa.id=x.farm_id where x.id=$1 for update of x;select fm.role into role from public.farm_members fm where fm.farm_id=f and fm.user_id=auth.uid()and fm.active;if role is null then raise exception'Production access denied'using errcode='42501';end if;if st<>'active'then raise exception'Closed flock'using errcode='22023';end if;if role='worker'and $2<>(now()at time zone tz)::date then raise exception'Workers may record current date only'using errcode='42501';end if;if $7>0 and not exists(select 1 from public.feed_types where id=$8 and farm_id=f and active)then raise exception'Valid feed type required'using errcode='23514';end if;available:=public.flock_balance_at($1,$2);if $5+$6>available then raise exception'Bird losses exceed available birds'using errcode='23514';end if;insert into public.daily_production_records(farm_id,flock_id,production_date,eggs_collected,cracked_eggs,deaths,culls,feed_consumed_kg,feed_type_id,transport_cost,other_cost,notes,created_by)values(f,$1,$2,$3,$4,$5,$6,$7,case when $7>0 then $8 end,$9,$10,nullif(trim($11),''),auth.uid())returning*into r;insert into public.egg_inventory_movements(farm_id,movement_date,movement_type,direction,quantity_eggs,source_type,source_id,created_by)values(f,$2,'production','IN',$3-$4,'daily_production',r.id,auth.uid());if $7>0 then insert into public.feed_inventory_movements(farm_id,flock_id,feed_type_id,movement_date,movement_type,direction,quantity_kg,source_type,source_id,created_by)values(f,$1,$8,$2,'consumption','OUT',$7,'daily_production',r.id,auth.uid());perform public.recalculate_feed_ledger(f,$8);end if;if $5>0 then insert into public.bird_movements(farm_id,flock_id,movement_date,movement_type,quantity,direction,source_type,source_id,created_by)values(f,$1,$2,'death',$5,'OUT','daily_production',r.id,auth.uid());end if;if $6>0 then insert into public.bird_movements(farm_id,flock_id,movement_date,movement_type,quantity,direction,source_type,source_id,created_by)values(f,$1,$2,'cull',$6,'OUT','daily_production',r.id,auth.uid());end if;perform public.assert_nonnegative_flock_history($1);return r;exception when unique_violation then raise exception'A production record already exists for this flock on this date'using errcode='23505';end;$$;
create function public.update_daily_production(target_production_id uuid,eggs_collected integer,cracked_eggs integer,deaths integer,culls integer,feed_consumed_kg numeric,feed_type_id uuid,transport_cost numeric,other_cost numeric,notes text default null)returns public.daily_production_records language plpgsql security definer set search_path='' as $$declare e public.daily_production_records;r public.daily_production_records;old_type uuid;begin select*into e from public.daily_production_records where id=$1 for update;if e.id is null or not public.has_farm_role(e.farm_id,array['admin','manager'])then raise exception'Production edit access denied'using errcode='42501';end if;if $6>0 and not exists(select 1 from public.feed_types where id=$7 and farm_id=e.farm_id and active)then raise exception'Valid feed type required'using errcode='23514';end if;old_type:=e.feed_type_id;delete from public.bird_movements where source_type='daily_production'and source_id=e.id and movement_type in('death','cull');delete from public.feed_inventory_movements where source_type='daily_production'and source_id=e.id and movement_type='consumption';update public.daily_production_records set eggs_collected=$2,cracked_eggs=$3,deaths=$4,culls=$5,feed_consumed_kg=$6,feed_type_id=case when $6>0 then $7 end,transport_cost=$8,other_cost=$9,notes=nullif(trim($10),''),updated_by=auth.uid()where id=e.id returning*into r;update public.egg_inventory_movements set quantity_eggs=$2-$3 where source_type='daily_production'and source_id=e.id and movement_type='production';if $6>0 then insert into public.feed_inventory_movements(farm_id,flock_id,feed_type_id,movement_date,movement_type,direction,quantity_kg,source_type,source_id,created_by)values(e.farm_id,e.flock_id,$7,e.production_date,'consumption','OUT',$6,'daily_production',e.id,auth.uid());end if;if old_type is not null then perform public.recalculate_feed_ledger(e.farm_id,old_type);end if;if $7 is not null and $7 is distinct from old_type then perform public.recalculate_feed_ledger(e.farm_id,$7);end if;if $4>0 then insert into public.bird_movements(farm_id,flock_id,movement_date,movement_type,quantity,direction,source_type,source_id,created_by)values(e.farm_id,e.flock_id,e.production_date,'death',$4,'OUT','daily_production',e.id,auth.uid());end if;if $5>0 then insert into public.bird_movements(farm_id,flock_id,movement_date,movement_type,quantity,direction,source_type,source_id,created_by)values(e.farm_id,e.flock_id,e.production_date,'cull',$5,'OUT','daily_production',e.id,auth.uid());end if;perform public.assert_nonnegative_flock_history(e.flock_id);return r;end;$$;
create or replace function public.delete_daily_production(target_production_id uuid)returns void language plpgsql security definer set search_path='' as $$declare e public.daily_production_records;t uuid;begin select*into e from public.daily_production_records where id=$1 for update;if e.id is null or not public.has_farm_role(e.farm_id,array['admin'])then raise exception'Admin access required'using errcode='42501';end if;t:=e.feed_type_id;delete from public.bird_movements where source_type='daily_production'and source_id=e.id;delete from public.egg_inventory_movements where source_type='daily_production'and source_id=e.id;delete from public.feed_inventory_movements where source_type='daily_production'and source_id=e.id;delete from public.daily_production_records where id=e.id;if t is not null then perform public.recalculate_feed_ledger(e.farm_id,t);end if;end;$$;

create view public.v_feed_purchase_receivables with(security_invoker=true)as select p.*,coalesce(sum(x.amount)filter(where x.voided_at is null),0)::numeric(14,2)total_paid,(p.total_cost-coalesce(sum(x.amount)filter(where x.voided_at is null),0))::numeric(14,2)outstanding_balance,case when coalesce(sum(x.amount)filter(where x.voided_at is null),0)=0 then'unpaid'when coalesce(sum(x.amount)filter(where x.voided_at is null),0)>=p.total_cost then'paid'else'partial'end payment_status from public.feed_purchases p left join public.feed_purchase_payments x on x.feed_purchase_id=p.id group by p.id;
create view public.v_feed_forecast with(security_invoker=true)as select ft.farm_id,ft.id feed_type_id,ft.name feed_type_name,coalesce(b.quantity_kg,0)quantity_kg,round(coalesce(b.quantity_kg,0)/ft.default_bag_size_kg,3)bag_equivalent,coalesce(b.inventory_value,0)inventory_value,coalesce(b.weighted_average_cost,0)weighted_average_cost,coalesce(avgx.average_daily_consumption,0)average_daily_consumption,case when coalesce(avgx.average_daily_consumption,0)>0 then round(coalesce(b.quantity_kg,0)/avgx.average_daily_consumption,2)end days_remaining,case when coalesce(avgx.average_daily_consumption,0)>0 then((now()at time zone f.timezone)::date+ceil(coalesce(b.quantity_kg,0)/avgx.average_daily_consumption)::integer)end estimated_finish_date,case when coalesce(b.quantity_kg,0)<=0 then'out_of_stock'when coalesce(avgx.average_daily_consumption,0)=0 then'unknown'when coalesce(b.quantity_kg,0)/avgx.average_daily_consumption<=fs.feed_alert_critical_days then'critical'when coalesce(b.quantity_kg,0)/avgx.average_daily_consumption<=fs.feed_alert_warning_days then'warning'else'healthy'end alert_level from public.feed_types ft join public.farms f on f.id=ft.farm_id join public.farm_settings fs on fs.farm_id=ft.farm_id left join public.feed_inventory_balances b on b.feed_type_id=ft.id left join lateral(select round(coalesce(sum(coalesce(d.usage,0)),0)/nullif(count(*),0),3)average_daily_consumption from(select distinct production_date from public.daily_production_records where farm_id=ft.farm_id order by production_date desc limit fs.average_feed_days_window)dates left join lateral(select sum(quantity_kg)usage from public.feed_inventory_movements where farm_id=ft.farm_id and feed_type_id=ft.id and movement_type='consumption'and movement_date=dates.production_date)d on true)avgx on true where ft.active;

alter table public.feed_types enable row level security;alter table public.suppliers enable row level security;alter table public.feed_purchases enable row level security;alter table public.feed_purchase_payments enable row level security;alter table public.feed_inventory_balances enable row level security;
create policy feed_types_read on public.feed_types for select to authenticated using(public.is_farm_member(farm_id));create policy suppliers_read on public.suppliers for select to authenticated using(public.has_farm_role(farm_id,array['admin','manager']));create policy feed_purchases_read on public.feed_purchases for select to authenticated using(public.has_farm_role(farm_id,array['admin','manager']));create policy feed_payments_read on public.feed_purchase_payments for select to authenticated using(public.has_farm_role(farm_id,array['admin','manager']));create policy feed_balances_read on public.feed_inventory_balances for select to authenticated using(public.is_farm_member(farm_id));
grant select on public.feed_types,public.feed_inventory_balances,public.v_feed_forecast to authenticated;grant select on public.suppliers,public.feed_purchases,public.feed_purchase_payments,public.v_feed_purchase_receivables to authenticated;grant all on public.feed_types,public.suppliers,public.feed_purchases,public.feed_purchase_payments,public.feed_inventory_balances to service_role;grant select on public.v_feed_forecast,public.v_feed_purchase_receivables to service_role;
revoke all on function public.recalculate_feed_ledger(uuid,uuid),public.feed_access_farm(text[])from public;
revoke all on function public.create_feed_type(text,numeric,text),public.update_feed_type(uuid,text,numeric,boolean,text),public.create_supplier(text,text,text,text,text),public.update_supplier(uuid,text,text,text,text,boolean,text),public.set_opening_feed_stock(uuid,date,numeric,numeric,numeric,text),public.post_feed_purchase(uuid,uuid,date,numeric,numeric,numeric,numeric,text,text,text),public.record_feed_purchase_payment(uuid,date,numeric,text,text,text),public.update_feed_purchase(uuid,uuid,date,numeric,numeric,numeric,text),public.void_feed_purchase_payment(uuid,text),public.void_feed_purchase(uuid,text),public.create_feed_adjustment(uuid,date,text,text,numeric,numeric,text,text),public.create_daily_production(uuid,date,integer,integer,integer,integer,numeric,uuid,numeric,numeric,text),public.update_daily_production(uuid,integer,integer,integer,integer,numeric,uuid,numeric,numeric,text)from public;
grant execute on function public.create_feed_type(text,numeric,text),public.update_feed_type(uuid,text,numeric,boolean,text),public.create_supplier(text,text,text,text,text),public.update_supplier(uuid,text,text,text,text,boolean,text),public.set_opening_feed_stock(uuid,date,numeric,numeric,numeric,text),public.post_feed_purchase(uuid,uuid,date,numeric,numeric,numeric,numeric,text,text,text),public.record_feed_purchase_payment(uuid,date,numeric,text,text,text),public.update_feed_purchase(uuid,uuid,date,numeric,numeric,numeric,text),public.void_feed_purchase_payment(uuid,text),public.void_feed_purchase(uuid,text),public.create_feed_adjustment(uuid,date,text,text,numeric,numeric,text,text),public.create_daily_production(uuid,date,integer,integer,integer,integer,numeric,uuid,numeric,numeric,text),public.update_daily_production(uuid,integer,integer,integer,integer,numeric,uuid,numeric,numeric,text)to authenticated;
